<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useUserInfoStore} from '@/stores/userInfo'
import {masterList,masterAudit,masterSave,type Master,type MasterEvent,type MasterKind,type MasterWrite} from '@/api/masters'
const user=useUserInfoStore(),kind=ref<MasterKind>('BRAND'),audit=ref(false),page=ref(1),total=ref(0),rows=ref<Master[]>([]),events=ref<MasterEvent[]>([])
const loading=ref(false),ready=ref(false),sending=ref(false),error=ref(''),message=ref(''),editing=ref(false),id=ref<string>(),version=ref(0),name=ref(''),description=ref(''),enabled=ref(true),note=ref(''),stale=ref(false)
const has=(code:string)=>user.permissions.some(p=>p.code===code)
const canCreate=computed(()=>has('masters.create')),canUpdate=computed(()=>has('masters.update'))
const pending=ref<{kind:MasterKind;id?:string;body:MasterWrite}>()
const labels={BRAND:'品牌',WORK:'作品',CATEGORY:'分類'}
function failure(e:any){return e.response?.data?.message||e.message||'暫時無法連線。'}
async function load(){loading.value=true;ready.value=false;error.value='';try{const r=audit.value?await masterAudit(page.value):await masterList(kind.value,page.value);total.value=r.total;if(audit.value)events.value=r.items as MasterEvent[];else rows.value=r.items as Master[];ready.value=true}catch(e){error.value=failure(e)}finally{loading.value=false}}
async function change(next:MasterKind|'AUDIT'){if(pending.value||sending.value||loading.value)return;editing.value=false;message.value='';audit.value=next==='AUDIT';if(next!=='AUDIT')kind.value=next;page.value=1;await load()}
function begin(row?:Master){if(!ready.value||pending.value||sending.value||!(row?canUpdate.value:canCreate.value))return;id.value=row?.id;version.value=row?.version||0;name.value=row?.name||'';description.value=row?.description||'';enabled.value=row?.enabled??true;note.value='';stale.value=false;editing.value=true;message.value='';error.value=''}
async function send(){if(sending.value)return;if(!pending.value){if(stale.value||!ready.value||!(id.value?canUpdate.value:canCreate.value))return;pending.value={kind:kind.value,id:id.value,body:{name:name.value.trim(),description:description.value.trim(),enabled:enabled.value,expectedVersion:version.value,requestId:crypto.randomUUID(),note:note.value.trim()}}}sending.value=true;error.value='';try{const p=pending.value;const r=await masterSave(p.kind,p.id,p.body);pending.value=undefined;editing.value=false;message.value=r.replayed?'操作已核對，沒有重複保存。':'主檔已保存並記錄稽核。';await load()}catch(e:any){const status=e.response?.status;if(status&&status>=400&&status<500){pending.value=undefined;stale.value=status===409;if(stale.value)ready.value=false;error.value=failure(e)+(stale.value?'；保留未送內容，請重讀後重新開啟編輯。':'')}else error.value='結果尚未確認。請重試同一操作，表單暫時凍結。'}finally{sending.value=false}}
function pretty(value:string|null){if(!value)return '—';try{return JSON.stringify(JSON.parse(value),null,2)}catch{return value}}
onMounted(load)
</script>
<template>
<section class="masters-panel card"><div class="card-body"><h1>品牌／作品／分類</h1><p>品牌與分類為必填，作品可選填。主檔不刪除；上架商品引用的主檔不能停用。改名保留 ID 與歷史訂單。</p>
<div class="actions"><button v-for="(label,k) in labels" :key="k" :disabled="loading||sending||!!pending" @click="change(k)">{{label}}</button><button v-if="has('masters.audit')" :disabled="loading||sending||!!pending" @click="change('AUDIT')">主檔稽核</button></div>
<h2>{{audit?'主檔稽核':labels[kind]+'主檔'}}</h2><p v-if="!canCreate&&!canUpdate&&!audit">目前為唯讀，不能新增或編輯主檔。</p><p role="alert" v-if="error">{{error}}</p><p role="status" v-if="message">{{message}}</p><p role="status" v-if="loading">載入中…</p>
<div class="actions"><button :disabled="loading||sending" @click="load">重讀資料</button><button v-if="!audit&&canCreate" :disabled="!ready||sending||!!pending" @click="begin()">新增{{labels[kind]}}</button></div>
<form v-if="editing" @submit.prevent="send"><h3>{{id?'編輯':'新增'}}{{labels[kind]}} <span v-if="id">· 版本 {{version}}</span></h3><fieldset :disabled="sending||!!pending||stale"><label>主檔名稱<input v-model="name" maxlength="80" required></label><label>主檔說明<textarea v-model="description" maxlength="500" /></label><label><input type="checkbox" v-model="enabled">啟用主檔</label><label>異動原因<textarea v-model="note" required maxlength="500" /></label></fieldset><button type="submit" :disabled="sending||stale||(!pending&&!ready)">{{pending?'重試同一操作':'保存主檔'}}</button><button type="button" :disabled="sending||!!pending" @click="editing=false">關閉編輯</button><p v-if="pending">待核對操作：{{pending.body.requestId}}。使用原內容重試；重整後先核對稽核。</p></form>
<div v-if="!audit" class="table-wrap"><table><thead><tr><th>名稱</th><th>說明</th><th>狀態</th><th>版本</th><th>操作</th></tr></thead><tbody><tr v-for="m in rows" :key="m.id"><td>{{m.name}}</td><td>{{m.description}}</td><td>{{m.enabled?'啟用':'停用'}}</td><td>{{m.version}}</td><td><button v-if="canUpdate" :disabled="!ready||!!pending||sending" @click="begin(m)">編輯 {{m.name}}</button></td></tr></tbody></table><p v-if="ready&&!rows.length">尚無此類主檔。</p></div>
<div v-else><p>時間為 Asia/Taipei；操作紀錄唯讀。</p><details v-for="e in events" :key="e.requestId"><summary>{{e.createdAt}} · {{labels[e.kind]}} · {{e.action}} · {{e.actorUsername}}</summary><p>操作 ID：{{e.requestId}}</p><p>原因：{{e.note}}</p><h3>修改前</h3><pre>{{pretty(e.beforeState)}}</pre><h3>修改後</h3><pre>{{pretty(e.afterState)}}</pre></details></div>
<div class="actions"><button :disabled="page===1||loading||sending||!!pending" @click="page--;load()">上一頁</button><span>第 {{page}} 頁 · 共 {{total}} 筆</span><button :disabled="page*20>=total||loading||sending||!!pending" @click="page++;load()">下一頁</button></div></div></section>
</template>
<style scoped>
.masters-panel{min-width:0;max-width:1400px}.masters-panel h1{font-size:1.5rem}.masters-panel h2{font-size:1.2rem}.masters-panel h3{font-size:1rem}.masters-panel p,td,pre{overflow-wrap:anywhere}.actions{display:flex;gap:.7rem;flex-wrap:wrap;margin:1rem 0;align-items:center}.masters-panel button{padding:.5rem .7rem;border:1px solid #385a61;border-radius:5px;background:white;color:#173e46}.masters-panel button:disabled{opacity:.5}.masters-panel form{border:1px solid #ccd5d8;padding:1rem;margin:1rem 0}.masters-panel label{display:block;margin:.7rem 0}.masters-panel input:not([type=checkbox]),textarea{display:block;width:100%;max-width:32rem;padding:.5rem}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse}td,th{text-align:left;border-bottom:1px solid #ddd;padding:.7rem}details{padding:.7rem;border-bottom:1px solid #ddd}pre{white-space:pre-wrap}fieldset{min-width:0}[role=alert]{color:#a32727}
</style>
